 "servings": 4, "prep_time_min": 5, "cook_time_min": 15, "notes": null, "nutrition": {"calories": 343.0, "protein_g": 12.5, "carbs_g": 72.0, "fat_g": 2.5, "sodium_mg": null, "fiber_g": null}, "source_name": "Better Health: Healthier Families recipes", "source_url": "https://www.nhs.uk/healthier-families/recipes/perfect-pasta-and-tomato-sauce/", "source_license": "Contains public sector information licensed under the Open Government Licence v3.0.", "steps": ["Heat the oil in a saucepan or frying pan. Add the onion and cook over a medium heat for 3 to 4 minutes, until soft.", "Add the garlic, and cook gently for another minute. Add the chopped tomatoes, tomato purée and mixed herbs. Season with pepper and then simmer gently, stirring every now and again, for 15 minutes or until the sauce is thick and rich.", "After the sauce has been simmering for 8 to 10 minutes, start cooking the spaghetti according to pack instructions.", "Drain the spaghetti and serve with the sauce, topped with fresh basil or other chopped herbs, if you like."], "lines": [{"raw": "1 teaspoon olive oil", "name": "olive oil", "quantity": 1.0, "unit": "teaspoon", "prep_note": null, "is_optional": false, "is_alt": false}, {"raw": "1 small onion, finely chopped", "name": "onion", "quantity": 1.0, "unit": null, "prep_note": "finely chopped", "is_optional": false, "is_alt": false}, {"raw": "1 garlic clove, crushed or finely chopped", "name": "garlic", "quantity": 1.0, "unit": "clove", "prep_note": "crushed or finely chopped", "is_optional": false, "is_alt": false}, {"raw": "1 (400 g) can diced tomatoes", "name": "diced tomatoes", "quantity": 1.0, "unit": "can", "prep_note": null, "is_optional": false, "is_alt": false}, {"raw": "2 tablespoons tomato paste", "name": "tomato paste", "quantity": 2.0, "unit": "tablespoon", "prep_note": null, "is_optional": false, "is_alt": false}, {"raw": "2 teaspoons italian seasoning", "name": "italian seasoning", "quantity": 2.0, "unit": "teaspoon", "prep_note": null, "is